/// DNS verification settings for organization email domains.
#[derive(Clone)]
pub struct DomainOptions {
    /// TXT lookup (defaults to `node:dns/promises` `resolveTxt`); inject for tests or a DNS-over-HTTPS resolver.
    pub resolve_txt: Option<Callback>,
    /// Label under the domain that holds the TXT record (default `_better-iam-challenge`).
    pub record_name: Option<String>,
    /// Domains no tenant may claim; defaults to widely used consumer mailbox providers. Compared exactly.
    pub blocked_domains: Option<Vec<String>>,
}

/// A domain an organization claims; it becomes discoverable once a DNS TXT record proves control.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TenantDomain {
    #[serde(rename = "domain")]
    pub domain: String,
    #[serde(rename = "status")]
    pub status: String,
    #[serde(rename = "verificationToken")]
    pub verification_token: String,
    #[serde(rename = "createdAt")]
    pub created_at: f64,
    #[serde(rename = "createdBy")]
    pub created_by: String,
    #[serde(
        rename = "verifiedAt",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub verified_at: Option<f64>,
    #[serde(
        rename = "lastCheckedAt",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub last_checked_at: Option<f64>,
    #[serde(rename = "id")]
    pub id: String,
    #[serde(rename = "tenantId")]
    pub tenant_id: String,
    /// Optional database-enforced natural key, unique within collection and tenant.
    #[serde(rename = "uniqueKey", default, skip_serializing_if = "Option::is_none")]
    pub unique_key: Option<String>,
    /// Members this type does not declare.
    #[serde(flatten)]
    pub extra: Map<String, Value>,
}

